(4391040, 632375, 72070, '<td valign="top">amazing colours! great postprocessing, because even if you can tell it''s been processed, it just fits the image really well and isn''t overdone! great job!</td>', 'amazing colours! great postprocessing, because even if you can tell it''s been processed, it just fits the image really well and isn''t overdone! great job!', '2008-01-14 10:32:39.000000', NULL, 1),
(4391041, 631903, 58728, '<td valign="top">This is beautifully serene.  Love it.</td>', 'This is beautifully serene.  Love it.', '2008-01-14 10:33:32.000000', NULL, 1),
