(4391401, 632459, 77543, '<td valign="top">I think this would have been better horizontal.</td>', 'I think this would have been better horizontal.', '2008-01-14 13:43:37.000000', NULL, 1),
(4391403, 631592, 88010, '<td valign="top">Now those are some brightly colored rocks.</td>', 'Now those are some brightly colored rocks.', '2008-01-14 13:43:53.000000', NULL, 1),
(4391406, 632538, 36133, '<td valign="top">A pretty scene, and I like the color tones, but there doesn''t seem to be a main subject.</td>', 'A pretty scene, and I like the color tones, but there doesn''t seem to be a main subject.', '2008-01-14 13:44:36.000000', NULL, 1),
(4391407, 632847, 88010, '<td valign="top">The vignette adds nothing, therefore it distracts.</td>', 'The vignette adds nothing, therefore it distracts.', '2008-01-14 13:45:09.000000', NULL, 1),
(4391408, 632665, 35994, '<td valign="top">The red helicopter is a nice little addition, I might''ve cropped this so the boardwalk boards were straight along the bottom.</td>', 'The red helicopter is a nice little addition, I might''ve cropped this so the boardwalk boards were straight along the bottom.', '2008-01-14 13:45:11.000000', NULL, 1),
(4391409, 632495, 85886, '<td valign="top">I love this shot.  Feels like another I''ve seen recently but this really stands out for the lighting (and any tone mapping you''ve done is beautifully subtle).  Everything is pin sharp and there''s lovely balance between the silhouetted trees with the sunset backlit mound.  The water quality is perfect with interesting shapes formed by the falling water and misty loveliness underneath (which again is a lovely balance with the glass-like upper part).  Ribbon or a top 10...else I''ll personally start a witchhunt ;)</td>', 'I love this shot.  Feels like another I''ve seen recently but this really stands out for the lighting (and any tone mapping you''ve done is beautifully subtle).  Everything is pin sharp and there''s lovely balance between the silhouetted trees with the sunset backlit mound.  The water quality is perfect with interesting shapes formed by the falling water and misty loveliness underneath (which again is a lovely balance with the glass-like upper part).  Ribbon or a top 10...else I''ll personally start a witchhunt ;)', '2008-01-14 13:45:20.000000', NULL, 1),
(4391410, 630995, 88336, '<td valign="top">Good story.</td>', 'Good story.', '2008-01-14 13:45:43.000000', NULL, 1),
(4391413, 632817, 88010, '<td valign="top">The falls might be too centered. Perhaps cropping out the top would put the falls at the top third, leaving the river as the main focal point. As it is, the bright gray sky draws the eye.</td>', 'The falls might be too centered. Perhaps cropping out the top would put the falls at the top third, leaving the river as the main focal point. As it is, the bright gray sky draws the eye.', '2008-01-14 13:47:01.000000', NULL, 1),
(4391414, 631358, 88599, '<td valign="top">I like your composition. Nice title.</td>', 'I like your composition. Nice title.', '2008-01-14 13:47:13.000000', NULL, 1),
(4391416, 631246, 88599, '<td valign="top">I love your sky &amp; clouds.</td>', 'I love your sky & clouds.', '2008-01-14 13:48:23.000000', NULL, 1),
(4391417, 631592, 88599, '<td valign="top">I like the mist coming off the water.  The rock color is so rich.</td>', 'I like the mist coming off the water.  The rock color is so rich.', '2008-01-14 13:49:09.000000', NULL, 1),
(4391418, 632136, 88599, '<td valign="top">This is a beautiful photo.  Congrats!</td>', 'This is a beautiful photo.  Congrats!', '2008-01-14 13:49:53.000000', NULL, 1),
(4391420, 632788, 88599, '<td valign="top">Is seems that time is standing still.</td>', 'Is seems that time is standing still.', '2008-01-14 13:50:46.000000', NULL, 1),
(4391431, 632794, 35994, '<td valign="top">I think the brightness of the snow actually take a little away from this, just my 2 cents.</td>', 'I think the brightness of the snow actually take a little away from this, just my 2 cents.', '2008-01-14 13:53:14.000000', NULL, 1),
(4391436, 632773, 35994, '<td valign="top">I don''t think the water is quite clear enough, or has enough motion blur to really work here IMO, and I''m not sure what''s off to the right side maybe a stick?</td>', 'I don''t think the water is quite clear enough, or has enough motion blur to really work here IMO, and I''m not sure what''s off to the right side maybe a stick?', '2008-01-14 13:54:22.000000', NULL, 1),
(4391466, 632314, 23433, '<td valign="top">Cool shot, but I might try to lighten the levels a little. There is a little less detail in the lower right part of the shot.  Great shot though.</td>', 'Cool shot, but I might try to lighten the levels a little. There is a little less detail in the lower right part of the shot.  Great shot though.', '2008-01-14 14:17:08.000000', NULL, 1),
(4391472, 632716, 23433, '<td valign="top">Nice composition, great saturation, but a little too dark for my taste. In some cases you may have to risk a bit of pixilation, and bump up your iso, either get to the scene when there is more light.</td>', 'Nice composition, great saturation, but a little too dark for my taste. In some cases you may have to risk a bit of pixilation, and bump up your iso, either get to the scene when there is more light.', '2008-01-14 14:21:51.000000', NULL, 1),
(4391477, 631254, 40718, '<td valign="top">I love it.  Grain doesn''t do well on DPC, but I love it. I''m giving this a 10.</td>', 'I love it.  Grain doesn''t do well on DPC, but I love it. I''m giving this a 10.', '2008-01-14 14:24:28.000000', NULL, 1),
