(4391620, 632720, 16488, '<td valign="top">Seems familiar to me...looks like the Susquehanna River shot from the Exchange Street Bridge in Binghamton, NY! If it is, I can''t say I miss those gray skies... Very serene. I like the blues and how cold they make everything feel.</td>', 'Seems familiar to me...looks like the Susquehanna River shot from the Exchange Street Bridge in Binghamton, NY! If it is, I can''t say I miss those gray skies... Very serene. I like the blues and how cold they make everything feel.', '2008-01-14 15:29:44.000000', NULL, 1),
(4391622, 632376, 33352, '<td valign="top">A little hard on the eyes but good...</td>', 'A little hard on the eyes but good...', '2008-01-14 15:31:13.000000', NULL, 1),
(4391625, 631360, 41864, '<td valign="top">Beautiful scenery. Photo seems tilted though.</td>', 'Beautiful scenery. Photo seems tilted though.', '2008-01-14 15:32:38.000000', NULL, 1),
