(4391633, 632617, 23433, '<td valign="top">The reds orange, and browns looks a little un-natural. Great composition, but if you did some level adjustments I may try to re-work with cooler colors.</td>', 'The reds orange, and browns looks a little un-natural. Great composition, but if you did some level adjustments I may try to re-work with cooler colors.', '2008-01-14 15:36:04.000000', NULL, 1),
(4391640, 631686, 85886, '<td valign="top">Stunning - it''s the sharp reflections of the grasses in the water that take this from being really nice to great imho.  Also one of those shots where a clear sky really works in a very simple but beautiful composition.</td>', 'Stunning - it''s the sharp reflections of the grasses in the water that take this from being really nice to great imho.  Also one of those shots where a clear sky really works in a very simple but beautiful composition.', '2008-01-14 15:37:28.000000', NULL, 1),
(4391643, 632107, 33352, '<td valign="top">Now who do I know in the West...</td>', 'Now who do I know in the West...', '2008-01-14 15:38:12.000000', NULL, 1),
(4391644, 631726, 85886, '<td valign="top">The line of the bridge is beautiful, as are the colours which are done enough to make it look really juicy but not unnatural and overprocessed...nicely done.</td>', 'The line of the bridge is beautiful, as are the colours which are done enough to make it look really juicy but not unnatural and overprocessed...nicely done.', '2008-01-14 15:38:37.000000', NULL, 1),
(4391646, 632495, 33352, '<td valign="top">Like the use of the light to bring this alive...</td>', 'Like the use of the light to bring this alive...', '2008-01-14 15:40:06.000000', NULL, 1),
(4391647, 631403, 33352, '<td valign="top">Good mood in this photo...</td>', 'Good mood in this photo...', '2008-01-14 15:41:16.000000', NULL, 1),
