INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4391670, 631407, 23433, '<td valign="top">Cool!</td>', 'Cool!', '2008-01-14 15:47:58.000000', NULL, 1),
(4391671, 632875, 85886, '<td valign="top">The colours have been pushed too far for my liking - so my knee jerk reaction was dislike, but the longer I look at it the more it grows on me.  I can''t put my finger on it...it looks so ''colour by numbers'' but it works as a piece, moreso than most of the other more digital art that occasionally pops up.  I''d have this on my wall, and that''s my acid test to see if I really like an image.</td>', 'The colours have been pushed too far for my liking - so my knee jerk reaction was dislike, but the longer I look at it the more it grows on me.  I can''t put my finger on it...it looks so ''colour by numbers'' but it works as a piece, moreso than most of the other more digital art that occasionally pops up.  I''d have this on my wall, and that''s my acid test to see if I really like an image.', '2008-01-14 15:47:59.000000', NULL, 1),
(4391674, 631824, 33352, '<td valign="top">Great reflection and presentation, good color and warmth..(just to be a little critical my head tilts to the left) Maybe just the perspective, still a 9.</td>', 'Great reflection and presentation, good color and warmth..(just to be a little critical my head tilts to the left) Maybe just the perspective, still a 9.', '2008-01-14 15:49:11.000000', NULL, 1),
(4391676, 632645, 85886, '<td valign="top">Beautiful shot (Jeff?) :)</td>', 'Beautiful shot (Jeff?) :)', '2008-01-14 15:50:03.000000', NULL, 1),
(4391677, 632834, 33352, '<td valign="top">With scenery and subjects like this how can one not score well  8</td>', 'With scenery and subjects like this how can one not score well  8', '2008-01-14 15:50:15.000000', NULL, 1),
(4391679, 632590, 33352, '<td valign="top">Are we back in iceland again, very nice use of color and perspective...8</td>', 'Are we back in iceland again, very nice use of color and perspective...8', '2008-01-14 15:51:32.000000', NULL, 1),
