(4396535, 632466, 83313, '<td valign="top">A little graininess showing in the water, but that is a tough item to get really smooth. I like the look of this.</td>', 'A little graininess showing in the water, but that is a tough item to get really smooth. I like the look of this.', '2008-01-16 11:02:33.000000', NULL, 1),
(4396543, 632379, 83313, '<td valign="top">I''m not caring for the crop, the image does not quite flow right, but he subject is interesting.</td>', 'I''m not caring for the crop, the image does not quite flow right, but he subject is interesting.', '2008-01-16 11:03:23.000000', NULL, 1),
(4396625, 632183, 86915, '<td valign="top">i love the look of the water</td>', 'i love the look of the water', '2008-01-16 11:29:53.000000', NULL, 1),
