(4396628, 632693, 86915, '<td valign="top">this is beautiful</td>', 'this is beautiful', '2008-01-16 11:30:14.000000', NULL, 1),
(4396653, 632760, 83313, '<td valign="top">I think a tighter crop of the stream may have worked better here. It would have  shown the great details of all those rocks in the stream bed. As it is, I don''t find it works, the composition seems to not flow right. The stream bed in the foreground is clearly the subject, but the composition draws my eye away from it.</td>', 'I think a tighter crop of the stream may have worked better here. It would have  shown the great details of all those rocks in the stream bed. As it is, I don''t find it works, the composition seems to not flow right. The stream bed in the foreground is clearly the subject, but the composition draws my eye away from it.', '2008-01-16 11:35:01.000000', NULL, 1),
(4396695, 631552, 83313, '<td valign="top">The rocks in the foreground are awesome. I don''t care for the way the falls fit into the upper left area. Maybe a tighter crop up there, but then you would lose some of those great rocks as well. I''m being excessively picky, there, because this is a great shot.</td>', 'The rocks in the foreground are awesome. I don''t care for the way the falls fit into the upper left area. Maybe a tighter crop up there, but then you would lose some of those great rocks as well. I''m being excessively picky, there, because this is a great shot.', '2008-01-16 11:44:59.000000', NULL, 1),
(4396698, 632716, 83313, '<td valign="top">Smooth and gentle looking. I could nap here</td>', 'Smooth and gentle looking. I could nap here', '2008-01-16 11:45:42.000000', NULL, 1),
(4396707, 631950, 83313, '<td valign="top">An awesome view, but perhaps a little too wide a view. My eye is drawn to that background instead of the awesome foreground.</td>', 'An awesome view, but perhaps a little too wide a view. My eye is drawn to that background instead of the awesome foreground.', '2008-01-16 11:48:11.000000', NULL, 1),
(4396710, 632830, 83313, '<td valign="top">And she entered one of you on the other side, right?</td>', 'And she entered one of you on the other side, right?', '2008-01-16 11:48:58.000000', NULL, 1),
(4396718, 632447, 83313, '<td valign="top">The lighting washed out the details of the boathouse a bit. Maybe a touch too tight a crop up top for my taste. Still a solid 6 for me, though. I have some David Winter cottages that look almost like this.</td>', 'The lighting washed out the details of the boathouse a bit. Maybe a touch too tight a crop up top for my taste. Still a solid 6 for me, though. I have some David Winter cottages that look almost like this.', '2008-01-16 11:51:49.000000', NULL, 1),
(4396721, 632857, 83313, '<td valign="top">I can hear the crickets chirping in this one.</td>', 'I can hear the crickets chirping in this one.', '2008-01-16 11:52:38.000000', NULL, 1),
(4396731, 632832, 83313, '<td valign="top">The contrast seems not quite strong enough to give this the impact it deserves. Great composition.</td>', 'The contrast seems not quite strong enough to give this the impact it deserves. Great composition.', '2008-01-16 11:55:54.000000', NULL, 1),
(4396739, 631129, 83313, '<td valign="top">Love it. Lots of great impact. Good strong colors without being oversaturated. The ripples from the duck add just the right touch to the image.</td>', 'Love it. Lots of great impact. Good strong colors without being oversaturated. The ripples from the duck add just the right touch to the image.', '2008-01-16 11:57:30.000000', NULL, 1),
(4396749, 631241, 83313, '<td valign="top">Great framing, silhouettes and display of the clouds. If I can nitpick about anything, it is maybe a touch too much sky drawing my gaze away from that awesome bridgescape. A new fave.</td>', 'Great framing, silhouettes and display of the clouds. If I can nitpick about anything, it is maybe a touch too much sky drawing my gaze away from that awesome bridgescape. A new fave.', '2008-01-16 12:01:30.000000', NULL, 1),
(4396755, 632574, 811, '<td valign="top">Nice simple composition, and I like the softness.</td>', 'Nice simple composition, and I like the softness.', '2008-01-16 12:03:30.000000', NULL, 1),
(4396758, 632538, 811, '<td valign="top">Good composition and I like the tree on the left.  I think ti would feel more balanced, though, if the rest of the bridge was showing.</td>', 'Good composition and I like the tree on the left.  I think ti would feel more balanced, though, if the rest of the bridge was showing.', '2008-01-16 12:04:09.000000', NULL, 1),
(4396976, 632645, 87539, '<td valign="top">Very nicely composed and the lighting is perfect IMO.</td>', 'Very nicely composed and the lighting is perfect IMO.', '2008-01-16 13:08:13.000000', NULL, 1),
(4396979, 632438, 87539, '<td valign="top">Nicely composed, would have liked to have seen a tighter crop on the right and bottom, otherwise well done.</td>', 'Nicely composed, would have liked to have seen a tighter crop on the right and bottom, otherwise well done.', '2008-01-16 13:10:17.000000', NULL, 1),
(4396987, 631673, 87539, '<td valign="top">I would have liked to have seen some of the blue in the sky, but the color play on the ripples is beautiful.</td>', 'I would have liked to have seen some of the blue in the sky, but the color play on the ripples is beautiful.', '2008-01-16 13:12:11.000000', NULL, 1),
(4396992, 632657, 87539, '<td valign="top">The bottom right is a tad distracting, overall a nice image.</td>', 'The bottom right is a tad distracting, overall a nice image.', '2008-01-16 13:13:04.000000', NULL, 1),
