(4401917, 630995, 79720, '<td valign="top">The (urban acid?) x-process is an interesting choice. I like the composition and title.</td>', 'The (urban acid?) x-process is an interesting choice. I like the composition and title.', '2008-01-18 05:03:13.000000', NULL, 1),
(4401918, 632376, 79720, '<td valign="top">Nice textures and reflections.</td>', 'Nice textures and reflections.', '2008-01-18 05:03:55.000000', NULL, 1),
(4401919, 632645, 79720, '<td valign="top">Great framing and awesome reflections. A pass through unsharp mask would really help the final image.</td>', 'Great framing and awesome reflections. A pass through unsharp mask would really help the final image.', '2008-01-18 05:05:19.000000', NULL, 1),
(4401920, 631552, 79720, '<td valign="top">Beautiful tones and well-composed.</td>', 'Beautiful tones and well-composed.', '2008-01-18 05:06:49.000000', NULL, 1),
(4401922, 632855, 79720, '<td valign="top">Well captured under some tricky lighting conditions.</td>', 'Well captured under some tricky lighting conditions.', '2008-01-18 05:11:10.000000', NULL, 1),
(4401924, 632635, 79720, '<td valign="top">I think you should try a pass through "unsharp mask". Seems to be some pixel softness.</td>', 'I think you should try a pass through "unsharp mask". Seems to be some pixel softness.', '2008-01-18 05:14:00.000000', NULL, 1),
(4401932, 632646, 79720, '<td valign="top">lol. Don''t mean to laugh out loud at your pain, but this is clever. I wonder if the voters will mark you up or down since they know it''s you? I''ll give you a 7, ''cause you nailed the DoF.</td>', 'lol. Don''t mean to laugh out loud at your pain, but this is clever. I wonder if the voters will mark you up or down since they know it''s you? I''ll give you a 7, ''cause you nailed the DoF.', '2008-01-18 05:26:09.000000', NULL, 1),
(4401935, 631824, 79720, '<td valign="top">Great rich tones and reflections.</td>', 'Great rich tones and reflections.', '2008-01-18 05:30:58.000000', NULL, 1),
(4402021, 631842, 88453, '<td valign="top">really great shot</td>', 'really great shot', '2008-01-18 07:14:07.000000', NULL, 1),
(4402023, 632645, 88453, '<td valign="top">great shot</td>', 'great shot', '2008-01-18 07:14:32.000000', NULL, 1),
(4402248, 631895, 41521, '<td valign="top">I like the old fashioned feel you''ve given this</td>', 'I like the old fashioned feel you''ve given this', '2008-01-18 09:38:58.000000', NULL, 1),
(4402253, 632035, 41521, '<td valign="top">Beautiful colors you''ve captured here, nice and sharp as well</td>', 'Beautiful colors you''ve captured here, nice and sharp as well', '2008-01-18 09:40:08.000000', NULL, 1),
(4402254, 632882, 41521, '<td valign="top">Overprocessed</td>', 'Overprocessed', '2008-01-18 09:40:50.000000', NULL, 1),
(4402256, 632014, 41521, '<td valign="top">A bit too abstract, i think</td>', 'A bit too abstract, i think', '2008-01-18 09:40:53.000000', NULL, 1),
(4402334, 631903, 51538, '<td valign="top">Lovely tranquil scene. 7.</td>', 'Lovely tranquil scene. 7.', '2008-01-18 10:22:20.000000', NULL, 1),
(4402335, 632648, 51538, '<td valign="top">It''s one of those gritty parts of the woods that always attracts...  wonderful photographic account of it too. 8</td>', 'It''s one of those gritty parts of the woods that always attracts...  wonderful photographic account of it too. 8', '2008-01-18 10:23:02.000000', NULL, 1),
(4402337, 631937, 51538, '<td valign="top">I like the rather unfocused sensation to your photo.</td>', 'I like the rather unfocused sensation to your photo.', '2008-01-18 10:23:29.000000', NULL, 1),
(4402340, 632711, 51538, '<td valign="top">The metallic foil-like sheen is rather spectacular.  The DOF is rather nice too. 7</td>', 'The metallic foil-like sheen is rather spectacular.  The DOF is rather nice too. 7', '2008-01-18 10:25:11.000000', NULL, 1),
(4402342, 631308, 51538, '<td valign="top">Simply pretty.  Remembrances of a year past.  Nice work.</td>', 'Simply pretty.  Remembrances of a year past.  Nice work.', '2008-01-18 10:25:54.000000', NULL, 1),
(4402344, 632857, 51538, '<td valign="top">Looks like an interesting mud puddle to explore.  My daughter and I keep aquatic garden aquariums and always enjoy such places...  I like the photo.</td>', 'Looks like an interesting mud puddle to explore.  My daughter and I keep aquatic garden aquariums and always enjoy such places...  I like the photo.', '2008-01-18 10:26:41.000000', NULL, 1),
(4402346, 631629, 51538, '<td valign="top">Lovely illustrative effect. 8.</td>', 'Lovely illustrative effect. 8.', '2008-01-18 10:27:03.000000', NULL, 1),
(4402435, 632850, 20530, '<td valign="top">Great time lapse. Nice mix of cool and warm colors. Beautiful contrast and detail. The only thing that I can think that would make this better would be to leave a little more room at the top. Lovely, image and I''m getting cold just looking at it. Good thing it''s 77 degrees here;)</td>', 'Great time lapse. Nice mix of cool and warm colors. Beautiful contrast and detail. The only thing that I can think that would make this better would be to leave a little more room at the top. Lovely, image and I''m getting cold just looking at it. Good thing it''s 77 degrees here;)', '2008-01-18 11:25:53.000000', NULL, 1),
(4402470, 631673, 41794, '<td valign="top">Love the warm rich colors and the ripple effect in the water.</td>', 'Love the warm rich colors and the ripple effect in the water.', '2008-01-18 11:58:29.000000', NULL, 1),
(4402471, 632744, 41794, '<td valign="top">Looks very frigid!</td>', 'Looks very frigid!', '2008-01-18 11:58:40.000000', NULL, 1),
(4402473, 632847, 41794, '<td valign="top">I definately like the composition you chose for this. The rocks in the foreground with the big cliffs in the background give a good perspective.</td>', 'I definately like the composition you chose for this. The rocks in the foreground with the big cliffs in the background give a good perspective.', '2008-01-18 11:59:21.000000', NULL, 1),
(4402475, 632654, 41794, '<td valign="top">Focus seems a little soft.</td>', 'Focus seems a little soft.', '2008-01-18 11:59:56.000000', NULL, 1),
(4402476, 632606, 41794, '<td valign="top">Nice capture! Not too sure on the "crooked" angle.</td>', 'Nice capture! Not too sure on the "crooked" angle.', '2008-01-18 12:00:25.000000', NULL, 1),
(4402480, 632416, 41794, '<td valign="top">Is that just cliff face on the far side? Almost looks like the foundations of an old building. I like the fall tonal colors in this, has a warm feeling.</td>', 'Is that just cliff face on the far side? Almost looks like the foundations of an old building. I like the fall tonal colors in this, has a warm feeling.', '2008-01-18 12:01:25.000000', NULL, 1),
(4402483, 631054, 41794, '<td valign="top">Looks like a pretty good flow for a creek!</td>', 'Looks like a pretty good flow for a creek!', '2008-01-18 12:02:36.000000', NULL, 1),
(4402798, 632375, 87539, '<td valign="top">Very beautiful, would be interesting if you could get the angle of the rocks to point directly at the angle made by the mountains in the upper left. I have to bump this one up from my original score!</td>', 'Very beautiful, would be interesting if you could get the angle of the rocks to point directly at the angle made by the mountains in the upper left. I have to bump this one up from my original score!', '2008-01-18 14:13:14.000000', NULL, 1),
(4402802, 632176, 87539, '<td valign="top">Interesting concept.  I would have liked to have seen the "river" flowing off the upper part of the photo.</td>', 'Interesting concept.  I would have liked to have seen the "river" flowing off the upper part of the photo.', '2008-01-18 14:15:09.000000', NULL, 1),
(4402811, 631136, 87539, '<td valign="top">The grassy bank in the corner is a tad distracting, and the river not showing signs of movement and being lighter in color than the sky is a bit surreal.  I love the mill though, the reflections are wonderful.</td>', 'The grassy bank in the corner is a tad distracting, and the river not showing signs of movement and being lighter in color than the sky is a bit surreal.  I love the mill though, the reflections are wonderful.', '2008-01-18 14:19:02.000000', NULL, 1),
(4402815, 632487, 87539, '<td valign="top">I like it, except it seems slightly tilted towards the left, which is bugging me.</td>', 'I like it, except it seems slightly tilted towards the left, which is bugging me.', '2008-01-18 14:20:16.000000', NULL, 1),
(4402816, 632715, 87539, '<td valign="top">I would have liked to have seen less blue sky, more river.</td>', 'I would have liked to have seen less blue sky, more river.', '2008-01-18 14:21:43.000000', NULL, 1),
(4402821, 631359, 87539, '<td valign="top">The clouds are really dominating, and my eye keeps jumping here there and everywhere.</td>', 'The clouds are really dominating, and my eye keeps jumping here there and everywhere.', '2008-01-18 14:23:33.000000', NULL, 1),
(4402825, 632687, 87539, '<td valign="top">I like the composition, but I''m wondering what this would look like in color.</td>', 'I like the composition, but I''m wondering what this would look like in color.', '2008-01-18 14:25:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4402837, 632127, 42256, '<td valign="top">Its always a pleasure seeing a shot from around Ithaca :)</td>', 'Its always a pleasure seeing a shot from around Ithaca :)', '2008-01-18 14:28:11.000000', NULL, 1),
(4402844, 632471, 87539, '<td valign="top">The colors and textures of the sky and river are great, but the trees just seem harsh against the softness of the rest of the photo.  I like the arrow made by the old pier/stumps that points me downriver.</td>', 'The colors and textures of the sky and river are great, but the trees just seem harsh against the softness of the rest of the photo.  I like the arrow made by the old pier/stumps that points me downriver.', '2008-01-18 14:29:32.000000', NULL, 1),
(4402847, 631308, 87539, '<td valign="top">The shadows from the branches are a little distracting, but I really like the way the water is around the leaf.</td>', 'The shadows from the branches are a little distracting, but I really like the way the water is around the leaf.', '2008-01-18 14:30:37.000000', NULL, 1),
(4402849, 632292, 87539, '<td valign="top">I''d like to see a little more texture in the sky, it''s so flat.</td>', 'I''d like to see a little more texture in the sky, it''s so flat.', '2008-01-18 14:31:19.000000', NULL, 1),
(4402889, 632656, 87539, '<td valign="top">I would have like to have seen more focus on the city instead of the nearby bank.</td>', 'I would have like to have seen more focus on the city instead of the nearby bank.', '2008-01-18 14:44:41.000000', NULL, 1),
(4402891, 632800, 87539, '<td valign="top">Is it just me, or is the background much darker than the foreground?  /The brightness of the few stalks of grass are distracting.</td>', 'Is it just me, or is the background much darker than the foreground?  /The brightness of the few stalks of grass are distracting.', '2008-01-18 14:46:06.000000', NULL, 1),
(4402895, 632700, 87539, '<td valign="top">The long exposure looks nice on the falls, but I don''t like how it washed them out at the bottom.</td>', 'The long exposure looks nice on the falls, but I don''t like how it washed them out at the bottom.', '2008-01-18 14:46:59.000000', NULL, 1),
(4402899, 632495, 87539, '<td valign="top">The reflections are nice, but the long exposure makes me think lazy river instead of one that is overflowing.</td>', 'The reflections are nice, but the long exposure makes me think lazy river instead of one that is overflowing.', '2008-01-18 14:48:11.000000', NULL, 1),
(4402900, 632891, 87539, '<td valign="top">Seems OOF to me.</td>', 'Seems OOF to me.', '2008-01-18 14:48:25.000000', NULL, 1),
(4402906, 632635, 87539, '<td valign="top">The building is stunning!  I don''t like that it''s centered though.</td>', 'The building is stunning!  I don''t like that it''s centered though.', '2008-01-18 14:49:05.000000', NULL, 1),
(4402907, 632595, 87539, '<td valign="top">A different angle and sharper focus on the bridge would have been nice.</td>', 'A different angle and sharper focus on the bridge would have been nice.', '2008-01-18 14:49:38.000000', NULL, 1),
(4402909, 632658, 87539, '<td valign="top">Long exposure looks great on the actual fall, but not on the rest of the water, and it seems to be a little OOF.</td>', 'Long exposure looks great on the actual fall, but not on the rest of the water, and it seems to be a little OOF.', '2008-01-18 14:50:30.000000', NULL, 1),
(4402911, 632093, 87539, '<td valign="top">I would have like to have seen if this creek bubbles and churns at all.</td>', 'I would have like to have seen if this creek bubbles and churns at all.', '2008-01-18 14:50:59.000000', NULL, 1),
(4402912, 631700, 87539, '<td valign="top">The lighting angles are interesting.</td>', 'The lighting angles are interesting.', '2008-01-18 14:51:42.000000', NULL, 1),
(4402915, 632188, 80859, '<td valign="top">the green of the fern leaves on the sides seem a little too bright to me.  i do love the way you did the colour of the water and the swirls in the foreground.  very nice overall.</td>', 'the green of the fern leaves on the sides seem a little too bright to me.  i do love the way you did the colour of the water and the swirls in the foreground.  very nice overall.', '2008-01-18 14:52:34.000000', NULL, 1),
(4402916, 632648, 87539, '<td valign="top">I like the tree with all it''s carvings, but would be nice to see more focus on the rope.</td>', 'I like the tree with all it''s carvings, but would be nice to see more focus on the rope.', '2008-01-18 14:52:37.000000', NULL, 1),
(4402922, 630936, 87539, '<td valign="top">The haze is interesting, I wonder what this would have looked like in b&amp;w.</td>', 'The haze is interesting, I wonder what this would have looked like in b&w.', '2008-01-18 14:54:50.000000', NULL, 1),
(4402925, 632010, 87539, '<td valign="top">Beautiful setting, but IMO the long exposure takes away from it.</td>', 'Beautiful setting, but IMO the long exposure takes away from it.', '2008-01-18 14:55:31.000000', NULL, 1),
(4402926, 631378, 87539, '<td valign="top">Nice composition, but IMO the long exposure takes away from the rushing water.</td>', 'Nice composition, but IMO the long exposure takes away from the rushing water.', '2008-01-18 14:55:57.000000', NULL, 1),
(4402928, 631552, 87539, '<td valign="top">I love the perspective, but not the long exposure.</td>', 'I love the perspective, but not the long exposure.', '2008-01-18 14:56:21.000000', NULL, 1),
(4402930, 630301, 87539, '<td valign="top">What a gorgeous waterfall, wish it weren''t so washed out at the bottom.</td>', 'What a gorgeous waterfall, wish it weren''t so washed out at the bottom.', '2008-01-18 14:56:47.000000', NULL, 1),
(4402932, 631937, 87539, '<td valign="top">The top half is overly busy and confusing.</td>', 'The top half is overly busy and confusing.', '2008-01-18 14:57:16.000000', NULL, 1),
(4402933, 632461, 87539, '<td valign="top">Very nice capture, would like to see more in focus than just the bird''s head.</td>', 'Very nice capture, would like to see more in focus than just the bird''s head.', '2008-01-18 14:57:49.000000', NULL, 1),
(4402936, 632188, 87539, '<td valign="top">Beautiful colors, but the long exposure makes it all look fake.</td>', 'Beautiful colors, but the long exposure makes it all look fake.', '2008-01-18 14:58:17.000000', NULL, 1),
(4403196, 632645, 67363, '<td valign="top">just beautiful</td>', 'just beautiful', '2008-01-18 17:32:38.000000', NULL, 1),
(4403241, 632645, 54878, '<td valign="top">Great shot, the reflection is spot on.  The only thing that I can see to alter is to go for a lightly tighter crop at the bottom, so that the reflection of the bridge matches what you can see of the bridge itself.  9</td>', 'Great shot, the reflection is spot on.  The only thing that I can see to alter is to go for a lightly tighter crop at the bottom, so that the reflection of the bridge matches what you can see of the bridge itself.  9', '2008-01-18 18:19:48.000000', NULL, 1),
(4403433, 631890, 39850, '<td valign="top">8 - Nice image.  Difficult to appreciate at this size.</td>', '8 - Nice image.  Difficult to appreciate at this size.', '2008-01-18 20:31:56.000000', NULL, 1),
(4403454, 632295, 39850, '<td valign="top">8 - Very nice image and scene.  The more you look at it the more you appreciate it.  Some minor tweaks to the sky and a more refined crop would finish this off nicely, in my opinion.</td>', '8 - Very nice image and scene.  The more you look at it the more you appreciate it.  Some minor tweaks to the sky and a more refined crop would finish this off nicely, in my opinion.', '2008-01-18 20:42:22.000000', NULL, 1),
(4403486, 632788, 87539, '<td valign="top">Beautiful colors, the angle of the building seems off to me.</td>', 'Beautiful colors, the angle of the building seems off to me.', '2008-01-18 20:55:31.000000', NULL, 1),
(4403489, 632848, 87539, '<td valign="top">I like the composition, but not the long exposure.</td>', 'I like the composition, but not the long exposure.', '2008-01-18 20:55:58.000000', NULL, 1),
(4403492, 630694, 87539, '<td valign="top">Very interesting, I like how the water flows up and over the leaf.</td>', 'Very interesting, I like how the water flows up and over the leaf.', '2008-01-18 20:56:55.000000', NULL, 1),
(4403494, 632214, 87539, '<td valign="top">The background is really bright and washed out, and I''d like to see the other side of the bridge.</td>', 'The background is really bright and washed out, and I''d like to see the other side of the bridge.', '2008-01-18 20:57:49.000000', NULL, 1),
(4403496, 632761, 87539, '<td valign="top">I''d like to have seen the waterfall more in focus.</td>', 'I''d like to have seen the waterfall more in focus.', '2008-01-18 20:58:21.000000', NULL, 1),
(4403500, 631686, 87539, '<td valign="top">I like the b&amp;w, but the water looks almost too smooth.</td>', 'I like the b&w, but the water looks almost too smooth.', '2008-01-18 20:59:43.000000', NULL, 1),
(4403503, 632640, 87539, '<td valign="top">I like the lighting in this photo.</td>', 'I like the lighting in this photo.', '2008-01-18 21:00:37.000000', NULL, 1),
(4403507, 632590, 87539, '<td valign="top">The long exposure just made this shot to surreal for me.</td>', 'The long exposure just made this shot to surreal for me.', '2008-01-18 21:01:03.000000', NULL, 1),
(4403514, 632641, 87539, '<td valign="top">The trees just seem to take something away from this photo.</td>', 'The trees just seem to take something away from this photo.', '2008-01-18 21:02:01.000000', NULL, 1),
(4403524, 632055, 87539, '<td valign="top">I would have like to have seen a straighter horizon and a bit more contrast</td>', 'I would have like to have seen a straighter horizon and a bit more contrast', '2008-01-18 21:07:38.000000', NULL, 1),
(4403526, 631283, 87539, '<td valign="top">I really like the idea, but the washed out snow on each side is distracting.</td>', 'I really like the idea, but the washed out snow on each side is distracting.', '2008-01-18 21:08:40.000000', NULL, 1),
(4403529, 632687, 65234, '<td valign="top">Lovely in B&amp;W.  The curve of the river pulls me in and there is something to see no matter how far I look.  Beatifully detailed and serene.</td>', 'Lovely in B&W.  The curve of the river pulls me in and there is something to see no matter how far I look.  Beatifully detailed and serene.', '2008-01-18 21:10:45.000000', NULL, 1),
(4403530, 632857, 65234, '<td valign="top">This looks like it should be harboring dinosaurs!  Gorgeous colors and lighting and fascinating composition.</td>', 'This looks like it should be harboring dinosaurs!  Gorgeous colors and lighting and fascinating composition.', '2008-01-18 21:10:49.000000', NULL, 1),
(4403531, 631552, 65234, '<td valign="top">The foreground rocks really add a lot to this scene.  Foreground water retains a bit of texture in the flow, too, which I personally prefer.  Colors are not overdone and the composition is very nice.</td>', 'The foreground rocks really add a lot to this scene.  Foreground water retains a bit of texture in the flow, too, which I personally prefer.  Colors are not overdone and the composition is very nice.', '2008-01-18 21:10:53.000000', NULL, 1),
(4403532, 631890, 65234, '<td valign="top">The bird really elevates this shot from good to great.  Pastels and light are beautifully soft and there is a marvelously peaceful feel to the scene, and I would like it without the bird, but I LOVE it with the bird and its flight path reflection leading my eye into the shot.</td>', 'The bird really elevates this shot from good to great.  Pastels and light are beautifully soft and there is a marvelously peaceful feel to the scene, and I would like it without the bird, but I LOVE it with the bird and its flight path reflection leading my eye into the shot.', '2008-01-18 21:10:56.000000', NULL, 1),
(4403533, 632226, 65234, '<td valign="top">What a fun scene to stimulate the imagination :-)  The evergreens are a perfect color to set off the snow (which is nicely textured, BTW) and stream.</td>', 'What a fun scene to stimulate the imagination :-)  The evergreens are a perfect color to set off the snow (which is nicely textured, BTW) and stream.', '2008-01-18 21:10:58.000000', NULL, 1),
(4403534, 632495, 65234, '<td valign="top">That sky is stunning.  Lovely, lovely tones here and great composition; I also like that the rivulets going over the little bridge are differentiated instead of being one big, white flow.</td>', 'That sky is stunning.  Lovely, lovely tones here and great composition; I also like that the rivulets going over the little bridge are differentiated instead of being one big, white flow.', '2008-01-18 21:11:02.000000', NULL, 1),
(4403535, 632416, 65234, '<td valign="top">Nice details and lighting in this.  Very 3-dimensional.  Nice natural tones, too.  You found a lot of beauty in this scene.</td>', 'Nice details and lighting in this.  Very 3-dimensional.  Nice natural tones, too.  You found a lot of beauty in this scene.', '2008-01-18 21:11:05.000000', NULL, 1),
(4403536, 632645, 70514, '<td valign="top">So beautiful.</td>', 'So beautiful.', '2008-01-18 21:11:13.000000', NULL, 1),
(4403538, 631919, 70514, '<td valign="top">Nice mix of subjects, great composition and natural framing.</td>', 'Nice mix of subjects, great composition and natural framing.', '2008-01-18 21:12:03.000000', NULL, 1),
(4403542, 631403, 65234, '<td valign="top">I love the silhouettes and reflections, and the tree I can just barely see in the fog.  The lead horse looks like he is carrying a burden, or is tired but determined to keep going, with the way his head is lowered.</td>', 'I love the silhouettes and reflections, and the tree I can just barely see in the fog.  The lead horse looks like he is carrying a burden, or is tired but determined to keep going, with the way his head is lowered.', '2008-01-18 21:13:37.000000', NULL, 1),
(4403543, 632107, 65234, '<td valign="top">What a fabulous perspective!  It looks almost like a little model of a futuristic city.</td>', 'What a fabulous perspective!  It looks almost like a little model of a futuristic city.', '2008-01-18 21:14:08.000000', NULL, 1),
(4403544, 631726, 70514, '<td valign="top">Great perspective to emphasise the size.  Lovely sky.</td>', 'Great perspective to emphasise the size.  Lovely sky.', '2008-01-18 21:14:15.000000', NULL, 1),
(4403545, 631903, 65234, '<td valign="top">Stunning reflections.  Blue tones are wondersul and I love the curves of the shoreline, covered in snow.</td>', 'Stunning reflections.  Blue tones are wondersul and I love the curves of the shoreline, covered in snow.', '2008-01-18 21:14:43.000000', NULL, 1),
(4403547, 632136, 70514, '<td valign="top">I really like the processing.</td>', 'I really like the processing.', '2008-01-18 21:15:23.000000', NULL, 1),
(4403550, 632214, 70514, '<td valign="top">Wonderful slice of red against the winter beauty.</td>', 'Wonderful slice of red against the winter beauty.', '2008-01-18 21:17:13.000000', NULL, 1),
(4403553, 632450, 70514, '<td valign="top">I''m not very fond of the warp on the trees.</td>', 'I''m not very fond of the warp on the trees.', '2008-01-18 21:18:08.000000', NULL, 1),
(4403554, 631903, 70514, '<td valign="top">Lovely glasslike water with very sharp reflections.  Nicely composed with such a strong leading line.</td>', 'Lovely glasslike water with very sharp reflections.  Nicely composed with such a strong leading line.', '2008-01-18 21:18:47.000000', NULL, 1),
(4403558, 632832, 70514, '<td valign="top">I love this in b/w.</td>', 'I love this in b/w.', '2008-01-18 21:21:20.000000', NULL, 1),
(4403574, 632459, 70514, '<td valign="top">I love this angle.  Wonderful lighting, colors and reflections.</td>', 'I love this angle.  Wonderful lighting, colors and reflections.', '2008-01-18 21:31:43.000000', NULL, 1),
(4403576, 632483, 70514, '<td valign="top">Reminds me of a vortex, love the little bits of water spots rushing through.</td>', 'Reminds me of a vortex, love the little bits of water spots rushing through.', '2008-01-18 21:32:37.000000', NULL, 1),
