(4404705, 630104, 811, '<td valign="top">I like how the water enters the frame at an angle.</td>', 'I like how the water enters the frame at an angle.', '2008-01-19 13:28:05.000000', NULL, 1),
(4404712, 631552, 811, '<td valign="top">This shot smells like achoo.  I like the perspective you have chosen.  Great colors and textures in the rocks and water.</td>', 'This shot smells like achoo.  I like the perspective you have chosen.  Great colors and textures in the rocks and water.', '2008-01-19 13:33:59.000000', NULL, 1),
(4404713, 632459, 811, '<td valign="top">I like the tilt you have chosen to use.</td>', 'I like the tilt you have chosen to use.', '2008-01-19 13:34:16.000000', NULL, 1),
(4404715, 631300, 811, '<td valign="top">I like the effect on the water.</td>', 'I like the effect on the water.', '2008-01-19 13:35:12.000000', NULL, 1),
(4404736, 630258, 811, '<td valign="top">This is pretty, but maybe a touch over saturated.</td>', 'This is pretty, but maybe a touch over saturated.', '2008-01-19 13:46:53.000000', NULL, 1),
(4404738, 632599, 811, '<td valign="top">A bit dark, but like a bug, I''m drawn to the bright areas.</td>', 'A bit dark, but like a bug, I''m drawn to the bright areas.', '2008-01-19 13:47:33.000000', NULL, 1),
(4404740, 632209, 811, '<td valign="top">Good composition.</td>', 'Good composition.', '2008-01-19 13:47:57.000000', NULL, 1),
(4404742, 631950, 811, '<td valign="top">I like the contrast between the land and water colors.</td>', 'I like the contrast between the land and water colors.', '2008-01-19 13:49:23.000000', NULL, 1),
(4404744, 632071, 811, '<td valign="top">Nice shot, more contrast in the buildings and better focus would make it more effective, I think.</td>', 'Nice shot, more contrast in the buildings and better focus would make it more effective, I think.', '2008-01-19 13:50:23.000000', NULL, 1),
(4404746, 632826, 811, '<td valign="top">A wider crop and better focus would make this a more effective shot.  Nice red, though.</td>', 'A wider crop and better focus would make this a more effective shot.  Nice red, though.', '2008-01-19 13:52:28.000000', NULL, 1),
(4404747, 632375, 811, '<td valign="top">The crop feels too narrow to me.  Nice colors and textures, though.</td>', 'The crop feels too narrow to me.  Nice colors and textures, though.', '2008-01-19 13:53:38.000000', NULL, 1),
(4404753, 632560, 811, '<td valign="top">Good symmetry between the two sides, but the color/lighting is a bit flat.</td>', 'Good symmetry between the two sides, but the color/lighting is a bit flat.', '2008-01-19 13:58:34.000000', NULL, 1),
(4404754, 632002, 811, '<td valign="top">You''ve at least got a trickle.</td>', 'You''ve at least got a trickle.', '2008-01-19 13:58:54.000000', NULL, 1),
(4404759, 632756, 811, '<td valign="top">Interesting shot.  I think a slightly less centered shot would have been more interesting.</td>', 'Interesting shot.  I think a slightly less centered shot would have been more interesting.', '2008-01-19 14:01:56.000000', NULL, 1),
(4404763, 632717, 811, '<td valign="top">It seems too bright to me.  The "brightness" is even throughout the shot, and if feels like it should have some darkness or shadows somewhere.</td>', 'It seems too bright to me.  The "brightness" is even throughout the shot, and if feels like it should have some darkness or shadows somewhere.', '2008-01-19 14:03:53.000000', NULL, 1),
(4404764, 632565, 811, '<td valign="top">This is very, very pretty.  Good composition and bw.</td>', 'This is very, very pretty.  Good composition and bw.', '2008-01-19 14:04:28.000000', NULL, 1),
(4404778, 632773, 811, '<td valign="top">Lots of movement.  Kinda flat though.  Maybe if the whites were brighter and the darks were more contrasted it would be more interesting.</td>', 'Lots of movement.  Kinda flat though.  Maybe if the whites were brighter and the darks were more contrasted it would be more interesting.', '2008-01-19 14:13:10.000000', NULL, 1),
(4404780, 631876, 811, '<td valign="top">Good composition, but it is a bit flat, tonally.</td>', 'Good composition, but it is a bit flat, tonally.', '2008-01-19 14:14:08.000000', NULL, 1),
(4404782, 632638, 811, '<td valign="top">Good composition and I like the lighting on this.</td>', 'Good composition and I like the lighting on this.', '2008-01-19 14:15:20.000000', NULL, 1),
(4404783, 632800, 811, '<td valign="top">I like the simplicity in colors in this one and how you have the grass in the foreground</td>', 'I like the simplicity in colors in this one and how you have the grass in the foreground', '2008-01-19 14:16:26.000000', NULL, 1),
(4404787, 631254, 811, '<td valign="top">Very mysterious looking</td>', 'Very mysterious looking', '2008-01-19 14:17:11.000000', NULL, 1),
(4404789, 632835, 811, '<td valign="top">I like the motion of the water, and you have a good contrast level in this.</td>', 'I like the motion of the water, and you have a good contrast level in this.', '2008-01-19 14:18:02.000000', NULL, 1),
(4404791, 632416, 811, '<td valign="top">This is great in many ways -- focus, lighting, coloring.  Very nicely done.</td>', 'This is great in many ways -- focus, lighting, coloring.  Very nicely done.', '2008-01-19 14:19:02.000000', NULL, 1),
(4404803, 632226, 88604, '<td valign="top">It would be better without the sword.</td>', 'It would be better without the sword.', '2008-01-19 14:32:45.000000', NULL, 1),
(4404805, 632744, 811, '<td valign="top">The sign is in focus, but because of the light across the way, the eye goes from the focused part to the unfocused part.  The overall result is that the focus needs to be stronger.</td>', 'The sign is in focus, but because of the light across the way, the eye goes from the focused part to the unfocused part.  The overall result is that the focus needs to be stronger.', '2008-01-19 14:34:09.000000', NULL, 1),
(4404807, 632379, 811, '<td valign="top">Nice bw.  Looks very "old."</td>', 'Nice bw.  Looks very "old."', '2008-01-19 14:36:22.000000', NULL, 1),
(4404808, 631903, 88604, '<td valign="top">Looks, or feels, like the horizon tilts to the right.</td>', 'Looks, or feels, like the horizon tilts to the right.', '2008-01-19 14:36:30.000000', NULL, 1),
(4404809, 632836, 811, '<td valign="top">Overall, I like the composition -- it almost has a minimalistic feeling to it.  I do think a stronger focus and exposure would be better.</td>', 'Overall, I like the composition -- it almost has a minimalistic feeling to it.  I do think a stronger focus and exposure would be better.', '2008-01-19 14:37:18.000000', NULL, 1),
(4404813, 631470, 811, '<td valign="top">I like the composition (is that a worm in the foreground?).  Lighting seems a bit harsh though.</td>', 'I like the composition (is that a worm in the foreground?).  Lighting seems a bit harsh though.', '2008-01-19 14:38:38.000000', NULL, 1),
(4404816, 631378, 811, '<td valign="top">Good composiiton.  Something about the rocks causes them to garner the viewers eye, though.</td>', 'Good composiiton.  Something about the rocks causes them to garner the viewers eye, though.', '2008-01-19 14:39:46.000000', NULL, 1),
(4404817, 631686, 811, '<td valign="top">Very simplistic and effective.</td>', 'Very simplistic and effective.', '2008-01-19 14:39:59.000000', NULL, 1),
(4404819, 632010, 88604, '<td valign="top">Good range of tones - nothing burned out, and nothing too dark. A little too saturated, and I would have liked to see the falls more to the right, and dead center.  Very nice photos.</td>', 'Good range of tones - nothing burned out, and nothing too dark. A little too saturated, and I would have liked to see the falls more to the right, and dead center.  Very nice photos.', '2008-01-19 14:40:26.000000', NULL, 1),
(4404821, 632313, 88604, '<td valign="top">I think it would have looked better without the tall structure on the right.</td>', 'I think it would have looked better without the tall structure on the right.', '2008-01-19 14:42:18.000000', NULL, 1),
(4404822, 632206, 811, '<td valign="top">I like the composition of this, and the details that are visible throughout.  However, there isn''t a lot to grab the viewer and compel them to stay with it.  Wonder if it would make a nice bw shot?</td>', 'I like the composition of this, and the details that are visible throughout.  However, there isn''t a lot to grab the viewer and compel them to stay with it.  Wonder if it would make a nice bw shot?', '2008-01-19 14:42:19.000000', NULL, 1),
(4404823, 632656, 811, '<td valign="top">Nice colors and composition.  I find myself trying to tilt it just a bit to the left, though.</td>', 'Nice colors and composition.  I find myself trying to tilt it just a bit to the left, though.', '2008-01-19 14:42:48.000000', NULL, 1),
(4404826, 630451, 811, '<td valign="top">Too much contrast, I think.</td>', 'Too much contrast, I think.', '2008-01-19 14:43:58.000000', NULL, 1),
(4404827, 632585, 811, '<td valign="top">I really like the high contrast and the bw in this.  However, focus seems way off (but not enough to be "soft focus").</td>', 'I really like the high contrast and the bw in this.  However, focus seems way off (but not enough to be "soft focus").', '2008-01-19 14:44:54.000000', NULL, 1),
(4404828, 632640, 811, '<td valign="top">Good capture.  The bird is a bit too centered though.</td>', 'Good capture.  The bird is a bit too centered though.', '2008-01-19 14:46:06.000000', NULL, 1),
(4404829, 632176, 811, '<td valign="top">Good details.  the crop feels a bit tight on the right.</td>', 'Good details.  the crop feels a bit tight on the right.', '2008-01-19 14:47:37.000000', NULL, 1),
(4404831, 631592, 88604, '<td valign="top">Nice, interesting image. I think it would have been better with less saturation.  Just to nit - the grass seems to conflict with the texture of the needles.  Take out the grass on the top right(different angle), and it would be much better.</td>', 'Nice, interesting image. I think it would have been better with less saturation.  Just to nit - the grass seems to conflict with the texture of the needles.  Take out the grass on the top right(different angle), and it would be much better.', '2008-01-19 14:49:22.000000', NULL, 1),
(4404832, 632711, 811, '<td valign="top">I like the warmth, and I like the calmness of the water.  The lighting on the trees on the right looks a bit out of place, though, and I hope you have a tilted horizon like that on purpose. :)</td>', 'I like the warmth, and I like the calmness of the water.  The lighting on the trees on the right looks a bit out of place, though, and I hope you have a tilted horizon like that on purpose. :)', '2008-01-19 14:49:50.000000', NULL, 1),
(4404833, 632888, 811, '<td valign="top">Good composition.  Wish the focus was a bit sharper throughout.</td>', 'Good composition.  Wish the focus was a bit sharper throughout.', '2008-01-19 14:50:14.000000', NULL, 1),
(4404837, 632758, 88604, '<td valign="top">Very nice photo except for the burned out sky.  I would have looked much better if you retained the color in the sky, and didn''t have the highlights blown out in the water.  You can do this with multiple exposures using tone mapping to create a High Dynamic Range (HDR) image.  //www.cambridgeincolour.com/tutorials/high-dynamic-range.htm</td>', 'Very nice photo except for the burned out sky.  I would have looked much better if you retained the color in the sky, and didn''t have the highlights blown out in the water.  You can do this with multiple exposures using tone mapping to create a High Dynamic Range (HDR) image.  //www.cambridgeincolour.com/tutorials/high-dynamic-range.htm', '2008-01-19 14:55:05.000000', NULL, 1),
(4404839, 632240, 811, '<td valign="top">This looks like the same place I voted on a minute ago. :)  I think the "white" sky is probably the biggest detriment to this shot.  I think if you could have somehow have gotten the reddish plant that is right in the middle as the subject, and let its reds stand out against the greens, it would have been more interesting.</td>', 'This looks like the same place I voted on a minute ago. :)  I think the "white" sky is probably the biggest detriment to this shot.  I think if you could have somehow have gotten the reddish plant that is right in the middle as the subject, and let its reds stand out against the greens, it would have been more interesting.', '2008-01-19 14:57:09.000000', NULL, 1),
(4404844, 632376, 88604, '<td valign="top">Great colors, graphic, and concept.  I would rate it two points higher if you had cropped out dark in the the upper left hand corner, which is distracting.  I would have preferred if you hadn''t tilted the image, but that''s just a personal preference.</td>', 'Great colors, graphic, and concept.  I would rate it two points higher if you had cropped out dark in the the upper left hand corner, which is distracting.  I would have preferred if you hadn''t tilted the image, but that''s just a personal preference.', '2008-01-19 15:02:24.000000', NULL, 1),
(4404846, 632699, 88604, '<td valign="top">Very interesting image.  You were able to avoid the dark blacks, and not burning out the whites at the same time.  I really like this image.</td>', 'Very interesting image.  You were able to avoid the dark blacks, and not burning out the whites at the same time.  I really like this image.', '2008-01-19 15:04:23.000000', NULL, 1),
(4404867, 632127, 811, '<td valign="top">That is a massive looking waterfall.  The overall tonality of the rocks (not the water) is kinda flat looking though.</td>', 'That is a massive looking waterfall.  The overall tonality of the rocks (not the water) is kinda flat looking though.', '2008-01-19 15:19:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4404868, 630999, 811, '<td valign="top">Cute shot, but way too saturated.</td>', 'Cute shot, but way too saturated.', '2008-01-19 15:20:48.000000', NULL, 1),
(4404869, 631534, 811, '<td valign="top">Almost abstract, in a way.  I like the reflection -- it looks like a big bug of somekind.</td>', 'Almost abstract, in a way.  I like the reflection -- it looks like a big bug of somekind.', '2008-01-19 15:21:27.000000', NULL, 1),
(4404872, 632861, 811, '<td valign="top">I am assuming they are literally in the spring and that it doesn''t refer to a season. :)  The people are a bit too small to be a significant part of the picture, but too big to not be a distraction.</td>', 'I am assuming they are literally in the spring and that it doesn''t refer to a season. :)  The people are a bit too small to be a significant part of the picture, but too big to not be a distraction.', '2008-01-19 15:23:32.000000', NULL, 1),
(4404875, 632875, 811, '<td valign="top">Way too saturated.  There is a lot of noise as a result.</td>', 'Way too saturated.  There is a lot of noise as a result.', '2008-01-19 15:25:12.000000', NULL, 1),
(4404876, 630096, 811, '<td valign="top">My kids love spots like this.  There are a seemingly endless supply of rocks to throw!</td>', 'My kids love spots like this.  There are a seemingly endless supply of rocks to throw!', '2008-01-19 15:25:53.000000', NULL, 1),
(4404878, 631726, 811, '<td valign="top">Nice colors and I like the perspective of the composition.</td>', 'Nice colors and I like the perspective of the composition.', '2008-01-19 15:26:24.000000', NULL, 1),
(4404880, 632438, 811, '<td valign="top">That is really pretty.  If you could have been there at a darker time of day, getting a longer exposure so the water looked "smoother" and not so choppy would have had a nice effect as well.</td>', 'That is really pretty.  If you could have been there at a darker time of day, getting a longer exposure so the water looked "smoother" and not so choppy would have had a nice effect as well.', '2008-01-19 15:27:45.000000', NULL, 1),
(4404881, 631283, 811, '<td valign="top">I like the overall whiteness of this.  It feels "insulated" despite the obvious cold.</td>', 'I like the overall whiteness of this.  It feels "insulated" despite the obvious cold.', '2008-01-19 15:28:23.000000', NULL, 1),
(4404883, 632857, 811, '<td valign="top">Good detail and lighting.</td>', 'Good detail and lighting.', '2008-01-19 15:29:45.000000', NULL, 1),
(4404885, 630647, 811, '<td valign="top">Good colors, but a bit blurry.</td>', 'Good colors, but a bit blurry.', '2008-01-19 15:30:33.000000', NULL, 1),
(4404890, 631291, 88604, '<td valign="top">Excellent concept, execution, and design.  Love the crispness and sharpness of the ice next to the slowness of the water.  Perhaps, maybe, the water motion could have been a little faster. I think a noise filter on the water would have helped too. 9</td>', 'Excellent concept, execution, and design.  Love the crispness and sharpness of the ice next to the slowness of the water.  Perhaps, maybe, the water motion could have been a little faster. I think a noise filter on the water would have helped too. 9', '2008-01-19 15:31:52.000000', NULL, 1),
(4404895, 632565, 88604, '<td valign="top">very peaceful, and tranquil.  Nice range of dark and light without too much of the white being lost.</td>', 'very peaceful, and tranquil.  Nice range of dark and light without too much of the white being lost.', '2008-01-19 15:32:47.000000', NULL, 1),
(4404897, 632855, 811, '<td valign="top">Nice colors in this.  Good capture.</td>', 'Nice colors in this.  Good capture.', '2008-01-19 15:33:19.000000', NULL, 1),
(4404900, 631358, 88604, '<td valign="top">Very very nice. Begs the question, did you place the seeds on the rock?  Doesn''t matter - still a great shot.  Nice colors, composition, balance, dof.  Good work.</td>', 'Very very nice. Begs the question, did you place the seeds on the rock?  Doesn''t matter - still a great shot.  Nice colors, composition, balance, dof.  Good work.', '2008-01-19 15:34:10.000000', NULL, 1),
(4404901, 632295, 811, '<td valign="top">I like the cool tones of this and how the river snakes through the frame</td>', 'I like the cool tones of this and how the river snakes through the frame', '2008-01-19 15:34:52.000000', NULL, 1),
(4404904, 631552, 88604, '<td valign="top">Very nice.  Love the detail in the pebbles, and the color in the water, and the falls not having the whites blown out. Nice composition.</td>', 'Very nice.  Love the detail in the pebbles, and the color in the water, and the falls not having the whites blown out. Nice composition.', '2008-01-19 15:35:45.000000', NULL, 1),
(4404906, 631291, 811, '<td valign="top">This is beautiful.  I love the coolness of it and the details of the ice on the side.  I also think it is a great contrast between the texture of the ice and the water in the background.</td>', 'This is beautiful.  I love the coolness of it and the details of the ice on the side.  I also think it is a great contrast between the texture of the ice and the water in the background.', '2008-01-19 15:36:17.000000', NULL, 1),
(4404908, 632764, 811, '<td valign="top">Very pretty.  I like that it has a deep dof.</td>', 'Very pretty.  I like that it has a deep dof.', '2008-01-19 15:36:51.000000', NULL, 1),
(4404910, 632464, 811, '<td valign="top">Nice sunset.  Having the horizon straight in the middle kinda gives it a static feeling, though.</td>', 'Nice sunset.  Having the horizon straight in the middle kinda gives it a static feeling, though.', '2008-01-19 15:37:25.000000', NULL, 1),
(4404913, 631903, 811, '<td valign="top">Very pretty.  The details are barely distinguishable in the snow, but otherwise a very well done shot.</td>', 'Very pretty.  The details are barely distinguishable in the snow, but otherwise a very well done shot.', '2008-01-19 15:38:37.000000', NULL, 1),
(4404915, 632873, 811, '<td valign="top">There are a lot of nice textures in this shot.  I''m wondering if a slightly longer shutter speed and a conversion to bw would make this have more punch.</td>', 'There are a lot of nice textures in this shot.  I''m wondering if a slightly longer shutter speed and a conversion to bw would make this have more punch.', '2008-01-19 15:40:09.000000', NULL, 1),
(4404918, 631552, 45857, '<td valign="top">Wonderful colors !!</td>', 'Wonderful colors !!', '2008-01-19 15:40:59.000000', NULL, 1),
(4404920, 632408, 811, '<td valign="top">I like the high contrast of this and the smoothness of the water.  I think if the structure was just a bit more to the right in the frame, it would outstanding compositionally as well.  Very nicely done.</td>', 'I like the high contrast of this and the smoothness of the water.  I think if the structure was just a bit more to the right in the frame, it would outstanding compositionally as well.  Very nicely done.', '2008-01-19 15:41:55.000000', NULL, 1),
(4404921, 631054, 811, '<td valign="top">Nice capture.  A bit too high in the contrast, I think.</td>', 'Nice capture.  A bit too high in the contrast, I think.', '2008-01-19 15:42:32.000000', NULL, 1),
(4404924, 632657, 811, '<td valign="top">I like the perspective and the "closeness" of this.  I think if the focus in the foreground was as sharp as the background it would be a very effective shot.</td>', 'I like the perspective and the "closeness" of this.  I think if the focus in the foreground was as sharp as the background it would be a very effective shot.', '2008-01-19 15:43:27.000000', NULL, 1),
(4404934, 631851, 88604, '<td valign="top">Great shot with some atmosphere!  Perhaps, maybe, perchance it could have use a little more contrast - on the dark side.  I would love to see what could have been done with a HDR image.  9<br/>//www.cambridgeincolour.com/tutorials/high-dynamic-range.htm</td>', 'Great shot with some atmosphere!  Perhaps, maybe, perchance it could have use a little more contrast - on the dark side.  I would love to see what could have been done with a HDR image.  9//www.cambridgeincolour.com/tutorials/high-dynamic-range.htm', '2008-01-19 15:46:02.000000', NULL, 1),
(4404938, 632645, 88604, '<td valign="top">Great image!  Nice composition, color, exposure.</td>', 'Great image!  Nice composition, color, exposure.', '2008-01-19 15:46:37.000000', NULL, 1),
(4404941, 632408, 88604, '<td valign="top">Nice image - you can almost feel the cold. I would have perhaps moved the wooden piles more off center - to the right a little.  But that''s just a nit.</td>', 'Nice image - you can almost feel the cold. I would have perhaps moved the wooden piles more off center - to the right a little.  But that''s just a nit.', '2008-01-19 15:47:45.000000', NULL, 1),
(4404950, 632711, 88604, '<td valign="top">Beautiful colors, but the horizon is not horizontal.</td>', 'Beautiful colors, but the horizon is not horizontal.', '2008-01-19 15:50:29.000000', NULL, 1),
(4404952, 632055, 88604, '<td valign="top">Nice shot, but the horizon is not horizontal</td>', 'Nice shot, but the horizon is not horizontal', '2008-01-19 15:51:02.000000', NULL, 1),
(4404958, 631673, 88604, '<td valign="top">Nice graphic image, but it''s too over saturated for me, and the background seems blurry.</td>', 'Nice graphic image, but it''s too over saturated for me, and the background seems blurry.', '2008-01-19 15:52:22.000000', NULL, 1),
(4404987, 632654, 87539, '<td valign="top">The glare from the sun really hurts this photo, a polarizing filter might have helped.</td>', 'The glare from the sun really hurts this photo, a polarizing filter might have helped.', '2008-01-19 16:18:38.000000', NULL, 1),
(4404990, 632857, 87539, '<td valign="top">I like the angles and focus of this shot. Well done.</td>', 'I like the angles and focus of this shot. Well done.', '2008-01-19 16:20:40.000000', NULL, 1),
(4404992, 632021, 87539, '<td valign="top">I like the composure, but the lighting seems a bit harsh.</td>', 'I like the composure, but the lighting seems a bit harsh.', '2008-01-19 16:22:23.000000', NULL, 1),
(4405032, 632635, 811, '<td valign="top">Beautiful shot.  Could possibly use a bit more contrast, but otherwise excellent</td>', 'Beautiful shot.  Could possibly use a bit more contrast, but otherwise excellent', '2008-01-19 16:45:35.000000', NULL, 1),
(4405040, 632724, 811, '<td valign="top">I like the "closeness" of this.  Good detail and clarity as well.</td>', 'I like the "closeness" of this.  Good detail and clarity as well.', '2008-01-19 16:49:22.000000', NULL, 1),
(4405043, 632088, 811, '<td valign="top">Good perspective and colors, but the other post processing is a bit much, I think.</td>', 'Good perspective and colors, but the other post processing is a bit much, I think.', '2008-01-19 16:50:40.000000', NULL, 1),
(4405044, 632811, 811, '<td valign="top">Very simply done.  And beautiful.</td>', 'Very simply done.  And beautiful.', '2008-01-19 16:51:00.000000', NULL, 1),
(4405051, 632292, 811, '<td valign="top">Good compostition.  the sky is featureless though and it takes up a big part of the frame.  that is detracting, I think</td>', 'Good compostition.  the sky is featureless though and it takes up a big part of the frame.  that is detracting, I think', '2008-01-19 16:53:22.000000', NULL, 1),
(4405055, 632583, 811, '<td valign="top">Good composition.  Maybe cropped a bit tight on the left.</td>', 'Good composition.  Maybe cropped a bit tight on the left.', '2008-01-19 16:55:08.000000', NULL, 1),
(4405057, 630965, 811, '<td valign="top">Nice shot -- good clarity and color.  I think some of the foreground could be cropped to give it a more balanced feeling.</td>', 'Nice shot -- good clarity and color.  I think some of the foreground could be cropped to give it a more balanced feeling.', '2008-01-19 16:56:16.000000', NULL, 1),
