INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4408542, 631824, 34938, '<td valign="top">This deserved a ribbon...I didn;t get to vote in this challenge, but man, you missed out!!! Stunning image and a fantastic title...well done my friend</td>', 'This deserved a ribbon...I didn;t get to vote in this challenge, but man, you missed out!!! Stunning image and a fantastic title...well done my friend', '2008-01-21 01:00:02.000000', NULL, 0),
(4408544, 632088, 83313, '<td valign="top">Great placement on this shot. I see from the other comments that you ran into the same thing with the obviously heavy PP that I have. Some love it and others hate it.</td>', 'Great placement on this shot. I see from the other comments that you ran into the same thing with the obviously heavy PP that I have. Some love it and others hate it.', '2008-01-21 01:00:28.000000', NULL, 0),
(4408548, 632495, 30861, '<td valign="top">I very much like the understated bleakness of this one. It speaks to a completely realistic, unromantic view of "winter"; nothing Currier-and-Ives about it :-) Congrats on 5th.</td>', 'I very much like the understated bleakness of this one. It speaks to a completely realistic, unromantic view of "winter"; nothing Currier-and-Ives about it :-) Congrats on 5th.', '2008-01-21 01:00:35.000000', NULL, 0),
(4408553, 632136, 41337, '<td valign="top">I agree with Jeb. Underrated.</td>', 'I agree with Jeb. Underrated.', '2008-01-21 01:01:06.000000', NULL, 0),
(4408555, 632008, 80167, '<td valign="top">Hey! Great picture of where I used to live! 10 years ago I lived in East Lyme and my backyard was Latimer Brook. My brothers and I would play in it all the time. Keep up the good work!</td>', 'Hey! Great picture of where I used to live! 10 years ago I lived in East Lyme and my backyard was Latimer Brook. My brothers and I would play in it all the time. Keep up the good work!', '2008-01-21 01:01:31.000000', NULL, 0),
(4408557, 631824, 30861, '<td valign="top">This is a very striking image, no question about it. An astonishingly high finish for such an artificial tweaking of the colors. Congrats on top 10 :-)</td>', 'This is a very striking image, no question about it. An astonishingly high finish for such an artificial tweaking of the colors. Congrats on top 10 :-)', '2008-01-21 01:01:41.000000', NULL, 0),
(4408559, 632021, 67579, '<td valign="top">hey Girl, wonderful shot I really liked this one in the challenge with the warm fall feel to it. Must be beautiful there also in the summer...<br/> <br/>-dave</td>', 'hey Girl, wonderful shot I really liked this one in the challenge with the warm fall feel to it. Must be beautiful there also in the summer... -dave', '2008-01-21 01:02:11.000000', NULL, 0),
