(4432110, 632088, 89418, '<td valign="top">I like the "glow" in this picture it is very nice.</td>', 'I like the "glow" in this picture it is very nice.', '2008-01-28 09:55:28.000000', NULL, 0),
(4432494, 631360, 66267, '<td valign="top">what''s this doing all the way down here? I thought this was among the best...</td>', 'what''s this doing all the way down here? I thought this was among the best...', '2008-01-28 11:22:42.000000', NULL, 0),
(4432599, 631403, 67697, '<td valign="top">Pretty and gritty.  I love the foggy/hazy mood. Beautiful capture of the reflections too.  Congrats on the 6+ score!</td>', 'Pretty and gritty.  I love the foggy/hazy mood. Beautiful capture of the reflections too.  Congrats on the 6+ score!', '2008-01-28 11:42:08.000000', NULL, 0),
(4433318, 631552, 87948, '<td valign="top">Fantastic foreground colours! :-)</td>', 'Fantastic foreground colours! :-)', '2008-01-28 14:20:52.000000', NULL, 0),
(4434795, 632654, 60862, '<td valign="top">Jojo - I like the composition.  I have a few suggestions, if you''re inclined to go back and take another crack at it.<br/> <br/>- Clone out the flare blob in the middle, in the trees<br/>- Try image-&gt;adjustments-&gt;shadow/highlight.  The top sliders will bring out detail in the shadows and the middle ones will bring out detail in blown highlights.  The entry seems a little too contrasty to me (and I love strong contrast).<br/>- The ripples in the water seem blurred in some places, but not in others.  That makes me wonder whether there was some noise reduction or blurring step in processing that went a little too far.<br/> <br/>I like the border. :)</td>', 'Jojo - I like the composition.  I have a few suggestions, if you''re inclined to go back and take another crack at it. - Clone out the flare blob in the middle, in the trees- Try image->adjustments->shadow/highlight.  The top sliders will bring out detail in the shadows and the middle ones will bring out detail in blown highlights.  The entry seems a little too contrasty to me (and I love strong contrast).- The ripples in the water seem blurred in some places, but not in others.  That makes me wonder whether there was some noise reduction or blurring step in processing that went a little too far. I like the border. :)', '2008-01-28 20:57:40.000000', NULL, 0),
(4434912, 632646, 63398, '<td valign="top">You are a sick puppy! I like that! LOL!!! Underrated but still such a great shot for the impact that the score doesn''t matter.</td>', 'You are a sick puppy! I like that! LOL!!! Underrated but still such a great shot for the impact that the score doesn''t matter.', '2008-01-28 21:21:37.000000', NULL, 0),
(4434936, 632646, 16531, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by NikonJeb:</b></div><hr/><i> You are a sick puppy! I like that! LOL!!! Underrated but still such a great shot for the impact that the score doesn''t matter. </i></td></tr></table> <br/> <br/>Ahh at last someone  finally knows that I am a sick puppy  LOL!!!!<br/>Thanks Jeb :)<br/><br/><i>Message edited by author 2008-01-28 21:29:43.</i></td>', 'Originally posted by NikonJeb: You are a sick puppy! I like that! LOL!!! Underrated but still such a great shot for the impact that the score doesn''t matter.   Ahh at last someone  finally knows that I am a sick puppy  LOL!!!!Thanks Jeb :)', '2008-01-28 21:29:07.000000', '2008-01-28 21:29:43.000000', 0),
(4436092, 632645, 81301, '<td valign="top">a very beautiful photo! love the light here, just perfect. very well deserved a ribbon. the light under the bridge is fantastic. thank you for taking the time to explain how you did it.</td>', 'a very beautiful photo! love the light here, just perfect. very well deserved a ribbon. the light under the bridge is fantastic. thank you for taking the time to explain how you did it.', '2008-01-29 09:48:54.000000', NULL, 0),
(4436682, 630999, 14986, '<td valign="top">I scored this one a "4" during the challenge.   The colors are off, which is the first thing people seem to be noticing.  The little girl also seems a little out of focus to me, which is probably from the slow shutter speed.  I would think on an outside shot, you should be able to work with a little higher shutter...at least a 1/60 would probably have made a difference here.<br/> <br/>You might also consider cropping some off of the top, as I think it would bring the viewer''s attention more to the subject.  Hope this is helpful!</td>', 'I scored this one a "4" during the challenge.   The colors are off, which is the first thing people seem to be noticing.  The little girl also seems a little out of focus to me, which is probably from the slow shutter speed.  I would think on an outside shot, you should be able to work with a little higher shutter...at least a 1/60 would probably have made a difference here. You might also consider cropping some off of the top, as I think it would bring the viewer''s attention more to the subject.  Hope this is helpful!', '2008-01-29 13:36:45.000000', NULL, 0),
(4436803, 631903, 42013, '<td valign="top">Your picture is definitely well done, of course the halos are a problem but get rid of those and it will be top notch!</td>', 'Your picture is definitely well done, of course the halos are a problem but get rid of those and it will be top notch!', '2008-01-29 14:36:34.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4437713, 632107, 22301, '<td valign="top">this is amazing, I like the wide angle high perspective.</td>', 'this is amazing, I like the wide angle high perspective.', '2008-01-29 21:12:53.000000', NULL, 0),
(4439634, 632641, 72268, '<td valign="top">This is very interesting. I love the angles and diagnals here. I wish the woman was either blurred or more in focus. Not sure. The water looks like mercury. Very nice shot.</td>', 'This is very interesting. I love the angles and diagnals here. I wish the woman was either blurred or more in focus. Not sure. The water looks like mercury. Very nice shot.', '2008-01-30 11:11:51.000000', NULL, 0),
(4441671, 631300, 17496, '<td valign="top">Excellent.  I can''t believe this didn''t rank higher.  I''m sick of typical waterfall/colored rocks/floating leaf picture.  The bark texture is excellent, and the hydraulic beauty of the picture is unique because of the swift water.  Loved it.</td>', 'Excellent.  I can''t believe this didn''t rank higher.  I''m sick of typical waterfall/colored rocks/floating leaf picture.  The bark texture is excellent, and the hydraulic beauty of the picture is unique because of the swift water.  Loved it.', '2008-01-30 20:26:46.000000', NULL, 0),
(4442133, 632635, 34113, '<td valign="top">Know the spot well and you got it when the crane wasn''t working on the library.</td>', 'Know the spot well and you got it when the crane wasn''t working on the library.', '2008-01-30 22:48:51.000000', NULL, 0),
(4448217, 632645, 61651, '<td valign="top">The arch and its reflection looks like a huge eye. :)  This is a very professional shot, Jeffrey.  Good job, and congrats on your ribbon!</td>', 'The arch and its reflection looks like a huge eye. :)  This is a very professional shot, Jeffrey.  Good job, and congrats on your ribbon!', '2008-02-01 17:41:46.000000', NULL, 0),
(4451677, 631378, 67145, '<td valign="top">WOW !!! .. glad you went with this one rather than your other possibles .. this is such an amazing photograph .. and your processing is brilliant .. love all the details and the way i''m drawn right into the image .. so many interesting things to see .. that waterfall, so well placed .... the water coming at you and the ''rapids'' .. so much movement .. love the trees in the background with the spindly trunks and those lucisy rocks .. !! ..:)</td>', 'WOW !!! .. glad you went with this one rather than your other possibles .. this is such an amazing photograph .. and your processing is brilliant .. love all the details and the way i''m drawn right into the image .. so many interesting things to see .. that waterfall, so well placed .... the water coming at you and the ''rapids'' .. so much movement .. love the trees in the background with the spindly trunks and those lucisy rocks .. !! ..:)', '2008-02-02 18:59:34.000000', NULL, 0),
(4456127, 630999, 68504, '<td valign="top">I dunno:  seems like the colour processing totally suits the subject - the girl and the gist.</td>', 'I dunno:  seems like the colour processing totally suits the subject - the girl and the gist.', '2008-02-04 02:08:26.000000', NULL, 0),
(4458287, 632200, 62318, '<td valign="top">Wonderful shot. I really like the physical elements here. The reflections are a terrific perk.</td>', 'Wonderful shot. I really like the physical elements here. The reflections are a terrific perk.', '2008-02-04 19:20:40.000000', NULL, 0),
(4488947, 632200, 30982, '<td valign="top">I think this came out pretty good, but as you note may be lacking a bit in the crispness and clarity that the ribbon winners get.  In part that could be the wide aperture - something at f/11 for instance might be crisper, though you''d have to jack up the ISO a bit to get there unless it''s dead calm and you have a tripod.  You''re definitely on the right track with the perspective - what may have hurt this a bit is the centeredness of the approach.  In essence, the composition is pulling is toward the eye of the culvert, which may not be the most attractive part of the composition.  Still, this did quite well, is a good shot, and is something you''ve not only learned from but will undoubtedly improve upon in the future.</td>', 'I think this came out pretty good, but as you note may be lacking a bit in the crispness and clarity that the ribbon winners get.  In part that could be the wide aperture - something at f/11 for instance might be crisper, though you''d have to jack up the ISO a bit to get there unless it''s dead calm and you have a tripod.  You''re definitely on the right track with the perspective - what may have hurt this a bit is the centeredness of the approach.  In essence, the composition is pulling is toward the eye of the culvert, which may not be the most attractive part of the composition.  Still, this did quite well, is a good shot, and is something you''ve not only learned from but will undoubtedly improve upon in the future.', '2008-02-15 14:26:37.000000', NULL, 0),
(4489449, 632010, 76430, '<td valign="top">I love Big Basin.  It''s a real peaceful sanctuary between the commotion of big cities.  I''ve been there twice over many years while traveling between Santa Cruz and San Jose.  I only saw forests, not any beautiful waterfalls like this.  Excellent shot.  It looks like light pouring off the cliff into the water.</td>', 'I love Big Basin.  It''s a real peaceful sanctuary between the commotion of big cities.  I''ve been there twice over many years while traveling between Santa Cruz and San Jose.  I only saw forests, not any beautiful waterfalls like this.  Excellent shot.  It looks like light pouring off the cliff into the water.', '2008-02-15 18:45:13.000000', NULL, 0),
(4493711, 631673, 48471, '<td valign="top">OOOOOO, WOW, this is beautiful! There are two different images here, the sky and the trees, in one side, and the water and the ripples, waves, on the other. I understand that it is difficult having a sharp photo with a 6.7 aperture, but I wish there was a bit more definition on the far field, like the clouds and the trees. The water itself is beautiful, it would be beautiful to have the lower part of the photo on a physics textbook. And the colours are beautiful, very nice, dynamic and appeased at the same time.</td>', 'OOOOOO, WOW, this is beautiful! There are two different images here, the sky and the trees, in one side, and the water and the ripples, waves, on the other. I understand that it is difficult having a sharp photo with a 6.7 aperture, but I wish there was a bit more definition on the far field, like the clouds and the trees. The water itself is beautiful, it would be beautiful to have the lower part of the photo on a physics textbook. And the colours are beautiful, very nice, dynamic and appeased at the same time.', '2008-02-18 02:23:05.000000', NULL, 0),
(4496790, 632886, 30982, '<td valign="top">Good for you on the manual thing!  I try that every now and then, but am not that comfortable with it either - so this is a good reminder that I should work with it more.  You captured the water well (which was the challenge) but the overall composition seems to be a bit lacking to me.  I often get the comment "there''s no where for the eye to go" on some of my stuff - I tend to do "too busy" - and I have to step back and see whether or not what I like will be of any interest to anyone else because of that.  Since I''m not familiar with the location, I can''t say whether a wider more encompassing shot would make a better composition, or a closer focus on the way the water moves across a particular section of rocks.  If you have the chance to shoot around here again, also try shooting from different angles if at all possible (without doing the Dr Achoo camera submersion trick!).</td>', 'Good for you on the manual thing!  I try that every now and then, but am not that comfortable with it either - so this is a good reminder that I should work with it more.  You captured the water well (which was the challenge) but the overall composition seems to be a bit lacking to me.  I often get the comment "there''s no where for the eye to go" on some of my stuff - I tend to do "too busy" - and I have to step back and see whether or not what I like will be of any interest to anyone else because of that.  Since I''m not familiar with the location, I can''t say whether a wider more encompassing shot would make a better composition, or a closer focus on the way the water moves across a particular section of rocks.  If you have the chance to shoot around here again, also try shooting from different angles if at all possible (without doing the Dr Achoo camera submersion trick!).', '2008-02-19 03:38:00.000000', NULL, 0),
(4504778, 632055, 26845, '<td valign="top">Diana I like this shot alot, its funny how people thought those logs jutting up out of the water looked like little sticks....</td>', 'Diana I like this shot alot, its funny how people thought those logs jutting up out of the water looked like little sticks....', '2008-02-21 15:09:44.000000', NULL, 0),
(4505767, 630999, 56880, '<td valign="top">I like the hyper-saturated look of this image; it fills the background with the energy of a small child, making the scene almost fantasy-like.  This should have scored much higher.</td>', 'I like the hyper-saturated look of this image; it fills the background with the energy of a small child, making the scene almost fantasy-like.  This should have scored much higher.', '2008-02-21 22:23:04.000000', NULL, 0),
(4509631, 631403, 70661, '<td valign="top">I didn''t vote in this challenge, Bob, but dang! This is awesome! Where did you take this at? Going in my favs!</td>', 'I didn''t vote in this challenge, Bob, but dang! This is awesome! Where did you take this at? Going in my favs!', '2008-02-23 10:47:25.000000', NULL, 0),
